function lineNear(sec){
  var ls=LX.lines, lo=0, hi=ls.length-1, best=-1;
  while(lo<=hi){ var mid=(lo+hi)>>1; if(ls[mid][0]<=sec){ best=mid; lo=mid+1; } else hi=mid-1; }
  if(best<0) return null;
  var e=ls[best], text=translatedLine(e[1]);
  if(sec-e[0]>6.5) return null;
  if(!text) return null;
  return {t:e[0], text:text.slice(0,lang==='en'?64:34), col:LX.col[e[2]]||'#888'};
}
function linesWindow(sec,half){
  var ls=LX.lines, lo=0, hi=ls.length-1;
  while(lo<=hi){ var mid=(lo+hi)>>1; if(ls[mid][0]<sec-half) lo=mid+1; else hi=mid-1; }
  var res=[];
  for(var i=lo;i<ls.length&&ls[i][0]<=sec+half;i++) res.push(ls[i]);
  return res;
}
function fmtTc(s){ var m=Math.floor(s/60), ss=Math.floor(s%60); return (m<10?'0':'')+m+':'+(ss<10?'0':'')+ss; }

