function loadFocus(index,done){
  if(!FOCUS.length)return;
  var resolved=((index%FOCUS.length)+FOCUS.length)%FOCUS.length;
  var item=FOCUS[resolved], token=++focusToken, im=new Image();
  im.decoding='async';
  im.onload=function(){
    if(token!==focusToken)return;
    gl.activeTexture(gl.TEXTURE5);
    gl.bindTexture(gl.TEXTURE_2D,focusTexture);
    gl.texImage2D(gl.TEXTURE_2D,0,gl.RGB,gl.RGB,gl.UNSIGNED_BYTE,im);
    focusNatural={w:im.naturalWidth,h:im.naturalHeight};
    gl.uniform2f(U.uFTexel,1/focusNatural.w,1/focusNatural.h);
    if(done)done(item,resolved);
  };
  im.onerror=function(){if(done)done(null,-1);};
  im.src=(useSmallFocus&&item.sm)?item.sm:item.lg;
}
function loadAtlas(index,done){
  var A=ATLAS[index],im=new Image();
  im.decoding='async';
  im.onload=function(){
    gl.activeTexture(gl.TEXTURE0+A.unit);
    gl.bindTexture(gl.TEXTURE_2D,A.texture);
    gl.texImage2D(gl.TEXTURE_2D,0,gl.RGB,gl.RGB,gl.UNSIGNED_BYTE,im);
    A.pxw=im.naturalWidth;A.pxh=im.naturalHeight;A.ready=true;
    atlasReady++;
    if(done) done();
  };
  im.onerror=function(){A.failed=true;if(done)done();};
  im.src=(useSmallAtlas&&A.sm)?A.sm:A.src;
}
/* The atlases form the moving environment; the foreground photograph is
   loaded separately at its full frame size. */
var atlasOrder=[2,3,0,4,1];
(function loadNext(pos){if(pos>=atlasOrder.length)return;loadAtlas(atlasOrder[pos],function(){setTimeout(function(){loadNext(pos+1);},pos<2?120:450);});})(0);
function tileRect(A, idx){
  var c=idx%A.cols, r=Math.floor(idx/A.cols);
  var iu=1.6/A.pxw, iv=1.6/A.pxh;
  return [c/A.cols+iu, r/A.rows+iv, 1/A.cols-2*iu, 1/A.rows-2*iv];
}

