/* ============ 回忆显影：1个完整前景 + 3个环境层 + 2个相遇轨道 ============ */
var slots=[]; for(var i=0;i<6;i++) slots.push({a:0,idx:-1,kind:0});
var nextAppAt=performance.now()+2500;
var capEls=[document.getElementById('cap0'),document.getElementById('cap1')];
function spawnAppar(orbit, midx, midy){
  var free=-1;
  var lo=orbit?4:1, hi=orbit?6:4;
  for(var i=lo;i<hi;i++) if(slots[i].a<.02){ free=i; break; }
  if(free<0) return;
  var age=ageS();
  if(!orbit && age<GATE.ghost) return;              /* 第一幕：只有灯、雾与月 */
  var sl=slots[free];
  var rr=Math.random();
  var A, kind;
  if(orbit){ kind=Math.random()<.5?2:3; A=ATLAS[kind]; if(!A.ready)return; }
  else if(age<GATE.hd || rr<.12){ A=Math.random()<.512?ATLAS[0]:ATLAS[1]; kind=(A===ATLAS[0]?0:1); }
  else if(age<GATE.mv || rr<.78){ kind=Math.random()<.5?2:3; A=ATLAS[kind]; }
  else if(age>=GATE.mv && rr<.91){ A=ATLAS[4]; kind=4; }
  else { kind=Math.random()<.5?2:3; A=ATLAS[kind]; }
  if(!A.ready){
    /* Dialogue and photographic atlases never substitute for one another. */
    var pool=kind<2?[0,1]:[2,3,4];
    var ready=pool.map(function(index){return {A:ATLAS[index],kind:index};}).filter(function(item){return item.A.ready;});
    if(!ready.length)return;
    var fallback=ready[Math.floor(Math.random()*ready.length)];A=fallback.A;kind=fallback.kind;
  }
  sl.kind=kind; sl.A=A;
  sl.idx= Math.floor(Math.random()*A.count);
  sl.t0=performance.now(); sl.phase=0; sl.reso=0;
  sl.orbit=orbit||null;
  if(orbit){
    sl.oa=Math.random()*6.283; sl.or=.34; sl.ox=midx; sl.oy=midy;
    sl.scale=.24+Math.random()*.10;
  } else {
    /* 回流：三成概率回到你抹过的地方 */
    var now=performance.now();
    var echo=wipeEcho.filter(function(w){return now-w.t<90000});
    if(echo.length && Math.random()<.3){
      var w=echo[Math.floor(Math.random()*echo.length)];
      sl.x=w.x+(Math.random()-.5)*.2; sl.y=w.y+(Math.random()-.5)*.15;
    } else {
      sl.x=view.x+(Math.random()-.5)*1.15;
      sl.y=view.y+(Math.random()-.5)*.6;
    }
    var mo=['push','pull','fall','still','drift'][Math.floor(Math.random()*5)];
    sl.motion=mo;
    sl.scale= [.18+Math.random()*.10, .18+Math.random()*.10, .48+Math.random()*.20, .48+Math.random()*.20, .46+Math.random()*.18][kind];
    sl.vx=(mo==='drift')?(Math.random()-.5)*.008:0;
    sl.vy=(mo==='fall')? -.010 : (mo==='drift'?(Math.random()-.5)*.005:.003);
  }
  stats.appar++;
}
/* ============ 开场序曲：进门就有东西看（其后交还给缓慢的世界） ============ */
function forceSpawn(kind,attempt){
  attempt=attempt||0;
  if(!ATLAS[kind].ready){if(!ATLAS[kind].failed&&attempt<24)setTimeout(function(){forceSpawn(kind,attempt+1);},900);return;}
  var free=-1; for(var i=1;i<4;i++) if(slots[i].a<.02){ free=i; break; }
  if(free<0) return;
  var sl=slots[free], A=ATLAS[kind];
  sl.kind=kind; sl.A=A; sl.idx=Math.floor(Math.random()*A.count);
  sl.t0=performance.now(); sl.phase=0; sl.reso=1; sl.orbit=null;
  sl.x=view.x+(Math.random()-.5)*.5; sl.y=view.y+(Math.random()-.5)*.28;
  sl.motion='still';
  sl.scale= kind<2? .20+Math.random()*.08 : (kind===4? .50+Math.random()*.14 : .52+Math.random()*.14);
  sl.vx=0; sl.vy=kind<2? .003 : 0;
  stats.appar++;
}
var focusCursor=3;
function spawnFocus(index){
  loadFocus(index,function(item,resolved){
    if(!item)return;
    var sl=slots[0];
    sl.kind=5;
    sl.A={cols:1,rows:1,count:1,pxw:focusNatural.w,pxh:focusNatural.h,ready:true};
    sl.idx=0;sl.focus=item;sl.focusIndex=resolved;
    sl.t0=performance.now();sl.phase=0;sl.reso=1;sl.orbit=null;sl.a=0;
    sl.x=view.x+(Math.random()-.5)*.12;
    sl.y=view.y+(Math.random()-.5)*.05;
    sl.motion='still';
    sl.scale=Math.max(.42,Math.min(.54,focusNatural.h/(2*cv.height)*.92));
    sl.vx=0;sl.vy=0;
    stats.appar++;
  });
}
setTimeout(function(){ if(ageS()<40) speakLine(0,{x:'你怎么来了',tc:'00:00:03',e:'How come you are here?',j:'どうして来たの？'}); },4500);
setTimeout(function(){ spawnFocus(focusCursor); },7000);
setTimeout(function(){ forceSpawn(0); },14500);    /* 一片台词雾影 */
setTimeout(function(){ forceSpawn(4); },22000);    /* 一条带命名与时间码的事件切片 */
setTimeout(function(){ if(!FX.busy && ageS()<70) runFx('sat'); },45000);   /* 怪事预告：07号卫星 */
setInterval(function(){
  if(!document.hidden&&!leftOnce){focusCursor=(focusCursor+7)%FOCUS.length;spawnFocus(focusCursor);}
},38000);
function stepAppars(now,dt,idle){
  if(now>nextAppAt){
    spawnAppar(false);
    nextAppAt=now+(idle?8000:11000)+Math.random()*8000;
  }
  var capUsed=0;
  for(var i=0;i<6;i++){
    var sl=slots[i];
    if(sl.idx<0){ gl.uniform4f(UAp[i],0,0,1,0); continue; }
    var age=(now-sl.t0)/1000;
    var life=sl.kind===5?36:(sl.orbit?14:30);
    var basePeak=[.25,.25,.96,.96,.93,1][sl.kind]||.4;
    var peak= sl.orbit? .72 : (idle? Math.min(1,basePeak*1.12) : basePeak);
    var a= age<9? peak*(age/9) : age<life-8? peak : age<life? peak*(1-(age-(life-8))/8) : 0;
    if(age>=life){ sl.idx=-1; gl.uniform4f(UAp[i],0,0,1,0); continue; }
    if(sl.orbit){
      sl.oa+=dt*.55; sl.or=Math.max(.08, sl.or-dt*.028);   /* 脸环吸入 */
      sl.x=sl.ox+Math.cos(sl.oa)*sl.or;
      sl.y=sl.oy+Math.sin(sl.oa)*sl.or*.7;
    } else {
      sl.x+=(sl.vx||0)*dt; sl.y+=(sl.vy||0)*dt;
      if(sl.motion==='push') sl.scale*= (1+dt*.012);
      if(sl.motion==='pull') sl.scale*= (1-dt*.009);
      /* 双频正弦漂移（MV工程公式的移植） */
      sl.x+=Math.sin(now/6000+i)*.00016+Math.sin(now/61000+i*2.1)*.0004;
    }
    sl.a=a;
    if(sl.kind===4 && !sl.reso && a>=.55){ sl.reso=1; resonate(sl); }
    gl.uniform4f(UAp[i], sl.x, sl.y, sl.scale, a);
    var R=sl.kind===5?[0,0,1,1]:tileRect(sl.A, sl.idx);
    var idx2=Math.min(sl.A.count-1, sl.idx+1);
    var R2=sl.kind===5?R:tileRect(sl.A, idx2);
    var mixv= (sl.kind>=2)? 0 : (.5+.5*Math.sin(now/1400+i*2.2))*.5;   /* 相邻帧微闪=活的片段 */
    gl.uniform4fv(UApR[i], R);
    gl.uniform4fv(UApR2[i], R2);
    gl.uniform2f(UApM[i], mixv, sl.kind);
    /* 锚点胶囊（v22语法）：台词帧显台词；事件切片显它的诗性命名 */
    if(capUsed<2 && a>.3 && (sl.kind<2 || sl.kind===4 || sl.kind===5)){
      var capTxt=null, capCol='#888';
      if(sl.kind===5){
        capTxt=fmtTc(sl.focus.time)+' / '+UI[lang].focus;capCol='#eef2f8';
      } else if(sl.kind===4){
        capTxt=labelFor(sl.idx); capCol='#c9d2e0';
        if(capTxt && MVTC && MVTC[sl.idx]>=0) capTxt=fmtTc(MVTC[sl.idx])+' / '+capTxt;
      } else {
        var sec=(sl.kind===0? sl.idx : 800+sl.idx)*6+3;
        var ln=lineNear(sec);
        if(ln){ capTxt=fmtTc(ln.t)+' / '+ln.text; capCol=ln.col; }
      }
      if(capTxt){
        var sp=toScreen(sl.x, sl.y - sl.scale*.62);
        if(sl.kind>=4) sp[1]=Math.min(sp[1], innerHeight-150-34*capUsed);   /* 大切片：命名收进画面下缘，双条错行 */
        if(sp[0]>60&&sp[0]<innerWidth-60&&sp[1]>80&&sp[1]<innerHeight-140){
          var el=capEls[capUsed++];
          el.querySelector('.cdot').style.background=capCol;
          el.querySelector('.ct').textContent=capTxt;
          el.style.left=sp[0]+'px'; el.style.top=sp[1]+'px';
          el.classList.add('on');
        }
      }
    }
  }
  for(var k=capUsed;k<2;k++) capEls[k].classList.remove('on');
}

/* ============ 帧循环 ============ */
var t0=performance.now(), frames=0, fpsT0=performance.now(), degraded=false, prevNow=performance.now(),rafId=0,rendering=true;
function frame(){
  if(!rendering)return;
  if(window.__glFail){rafId=requestAnimationFrame(frame);return;}
  var now=performance.now(), t=(now-t0)/1000*(reduced?.25:1);
  var dt=Math.min(.1,(now-prevNow)/1000); prevNow=now;
  view.x+=(viewT.x-view.x)*.02; view.y+=(viewT.y-view.y)*.02;
  touch.s+=(touchT-touch.s)*.06;
  if((now-lastInput)>2600) touchT*=.975;          /* 手离开，第五盏灯熄灭 */
  var idle=document.body.classList.contains('idle');
  idleAmt+=((idle?1:0)-idleAmt)*.02;
  dim+=(dimT-dim)*.02;
  /* 发呆时视野自己漫游 */
  if(idleAmt>.5 && !reduced){
    viewT.x=Math.sin(now/23000)*FIELD.x*.7;
    viewT.y=Math.cos(now/31000)*FIELD.y*.6;
  }
  /* 相遇调度（第四幕后开启） */
  if(!meetPair && now>nextMeetAt && ageS()>=GATE.meet){
    var pi=Math.floor(Math.random()*4), pj=(pi+1+Math.floor(Math.random()*3))%4;
    meetPair=[Math.min(pi,pj),Math.max(pi,pj)]; meetT0=now; meetMode=Math.floor(Math.random()*3);
  }
  var meetEase=0, meetMidX=view.x*.5, meetMidY=view.y*.5;
  if(meetPair){
    var mAge=(now-meetT0)/1000;
    meetEase= mAge<5? mAge/5 : mAge<12? 1 : mAge<16? (16-mAge)/4 : 0;
    if(mAge>=16){ meetPair=null; nextMeetAt=now+75000+Math.random()*60000; }
  }
  /* 灯：慢李萨如漫游全场域；发呆走向视野；按住被手吸引；相遇走向彼此 */
  for(var i=0;i<4;i++){
    var hx=homes[i][0],hy=homes[i][1];
    var a=(.20+.05*i)*.62,b=(.15+.04*i)*.62,ph=i*2.1;
    var lx=hx+Math.sin(t*a+ph)*.30+Math.cos(t*b*.7+ph)*.10;
    var ly=hy+Math.cos(t*b+ph)*.20+Math.sin(t*a*.6+ph)*.08;
    if(idleAmt>.02){
      lx=lx*(1-idleAmt*.55)+(view.x)*idleAmt*.55;
      ly=ly*(1-idleAmt*.55)+(view.y)*idleAmt*.55;
    }
    if(meetPair&&(i===meetPair[0]||i===meetPair[1])){
      var mx=(homes[meetPair[0]][0]+homes[meetPair[1]][0])*.5*.4+view.x*.5;
      var my=(homes[meetPair[0]][1]+homes[meetPair[1]][1])*.5*.4+view.y*.5;
      lx=lx*(1-meetEase*.85)+mx*meetEase*.85;
      ly=ly*(1-meetEase*.85)+my*meetEase*.85;
      meetMidX=mx; meetMidY=my;
    }
    if(touch.s>.72){
      var dtc=Math.hypot(touch.x-lx,touch.y-ly);
      if(dtc<.5){ var pull=(1-dtc/.5)*.45; lx=lx*(1-pull)+touch.x*pull; ly=ly*(1-pull)+touch.y*pull; }
    }
    /* 被接住的低语召唤：这盏灯滑向你的手，抵达后开口 */
    if(summon && summon.i===i){
      if(now>summon.until) summon=null;
      else {
        var sE=Math.min(1,(now-summon.t0)/1200);
        var sOut=Math.min(1,Math.max(0,(summon.until-now)/900));
        var sPull=.88*sE*sOut;
        lx=lx*(1-sPull)+touch.x*sPull;
        ly=ly*(1-sPull)+touch.y*sPull;
        if(!summon.spoke && sE>=1){ summon.spoke=true; speak(i); }
      }
    }
    lightsNow[i][0]=lx; lightsNow[i][1]=ly;
    /* 入场：四盏灯从雾深处逐一亮起（2/6.5/11/15.5秒，各7秒淡入） */
    lampEnt[i]=Math.min(1,Math.max(0,(ageS()-(2+i*4.5))/7));
    var inten=(.8+.25*Math.sin(t*.32+i*1.7))*lampEnt[i];
    if(FX.blackout){ var fl=Math.max(0,Math.sin((now-0)/23+i*9)*Math.sin(now/57+i*3)); inten*=fl*.25; }
    gl.uniform4f(UL[i],lx,ly,inten,0);
    var d=Math.hypot(touch.x-lx,touch.y-ly);
    if(d<.17&&touch.s>.2&&lampEnt[i]>.6){
      if(nearSince[i]<0) nearSince[i]=now;
      else if(now-nearSince[i]>1200&&(subTrack!==i||now>subUntil)){ speak(i); nearSince[i]=now-2200; }
    } else nearSince[i]=-1;
  }
  /* 相遇张力+对话+脸环 */
  var closeness=0;
  for(var i=0;i<3;i++)for(var j=i+1;j<4;j++){
    var dd=Math.hypot(lightsNow[i][0]-lightsNow[j][0],lightsNow[i][1]-lightsNow[j][1]);
    closeness=Math.max(closeness, 1-Math.min(1,dd/.5));
    if(dd<.16&&now>meetCd){
      var key=i+'-'+j, opts=MEETLINES[key];
      if(opts){
        meetPtr[key]=meetPtr[key]||0;
        speakMeet(i,j,opts[meetPtr[key]%opts.length]); meetPtr[key]++;
        var mx2=(lightsNow[i][0]+lightsNow[j][0])/2,my2=(lightsNow[i][1]+lightsNow[j][1])/2;
        addRip(mx2,my2,.08); addRip(mx2,my2,.05);
        spawnAppar({},mx2,my2); spawnAppar({},mx2,my2);   /* 脸环吸入 */
        stats.meets++;
      }
      meetCd=now+26000;
    }
  }
  meetAmp+=((meetPair?meetEase:0)*.85+closeness*.35-meetAmp)*.04;
  gl.uniform2f(U.uR,cv.width,cv.height);
  gl.uniform1f(U.uT,t);
  gl.uniform2f(U.uV,view.x,view.y);
  gl.uniform3f(U.uP,touch.x,touch.y,touch.s);
  gl.uniform1f(U.uDim,dim);
  gl.uniform1f(U.uQ,QUALITY);
  gl.uniform1f(U.uIdle,idleAmt);
  gl.uniform1f(U.uMeetA,Math.min(1,meetAmp));
  gl.uniform1f(U.uMeetT, meetPair? (now-meetT0)/1000 : 0);
  gl.uniform1f(U.uMeetM, meetMode);
  var audT=((document.body.classList.contains('idle') && (now-lastInput)>34000 && ageS()>=GATE.fx) || now<(FX.audUntil||0))? 1:0;
  FX.aud+=(audT-FX.aud)*.015;
  gl.uniform1f(U.uAud,FX.aud);
  gl.uniform3f(U.uDoor,FX.door.x,FX.door.y,FX.door.a||0);
  gl.uniform3f(U.uSat,FX.sat.x,FX.sat.y,0);
  gl.uniform1f(U.uMirror,FX.mirror||0);
  gl.uniform2f(U.uBleed,FX.bleed.p||0,FX.bleed.seed||0);
  gl.uniform2f(U.uJit, FX.weave? (Math.random()-.5)*.006*FX.weave : 0, FX.weave? (Math.random()-.5)*.009*FX.weave : 0);
  gl.uniform1f(U.uWeave,FX.weave||0);
  gl.uniform1f(U.uMoonB,FX.moonB||0);
  gl.uniform2f(U.uMeetP,meetMidX,meetMidY);
  for(var i=0;i<8;i++){
    var r=rips[i];
    if(r){ var age=(now-r.t0)/1000;
      if(age>2.6) gl.uniform4f(URip[i],0,0,0,0);
      else { gl.uniform4f(URip[i],r.x,r.y,age,r.amp); gl.uniform1f(URipF[i],r.f||46); }
    } else gl.uniform4f(URip[i],0,0,0,0);
  }
  stepAppars(now,dt,idle);
  gl.drawArrays(gl.TRIANGLES,0,3);
  frames++;
  if(!degraded&&now-fpsT0>4000){
    var fps=frames/((now-fpsT0)/1000);
    if(fps<26){
      degraded=true;
      QUALITY=.88;
      DPR=Math.max(1,Math.min(DPR,isTouch?1.5:1.65));
      size();
    }
    frames=0; fpsT0=now;
  }
  rafId=requestAnimationFrame(frame);
}
